8374: fn body_is_stack_chk_fail_only(body: &[HirNode], ctx: &PrintCtx) -> bool {
8375:     let mut meaningful = body.iter();
8376:     let Some(node) = meaningful.next() else {
8377:         return false;
8378:     };
8379:     meaningful.next().is_none() && node_is_stack_chk_fail_call(node, ctx)
8380: }
