8382: fn node_is_stack_chk_fail_call(node: &HirNode, ctx: &PrintCtx) -> bool {
8383:     match node {
8384:         HirNode::Statement(insn) => insn_calls_symbol(insn, "__stack_chk_fail", ctx),
8385:         HirNode::Block(children) => body_is_stack_chk_fail_only(children, ctx),
8386:         HirNode::Commented { inner, .. } => node_is_stack_chk_fail_call(inner, ctx),
8387:         _ => false,
8388:     }
8389: }
