8391: fn insn_calls_symbol(insn: &IrInsn, name: &str, ctx: &PrintCtx) -> bool {
8392:     if !matches!(insn.op, IrOp::Call | IrOp::Callind) {
8393:         return false;
8394:     }
8395:     let Some(target) = insn.inputs.first() else {
8396:         return false;
8397:     };
8398:     target.space == SpaceId::Const
8399:         && ctx
8400:             .symbols
8401:             .get(&target.offset)
8402:             .is_some_and(|sym| sym == name || sym.ends_with(name))
8403: }
